mapper.select:
SELECT c.id AS cameraId, c.device_name AS deviceName, c.serial_no AS deviceSerial, c.channel_no AS channelNo, COUNT(ps.id)::bigint AS sessionCount, COALESCE(SUM( CASE WHEN ps.id IS NULL THEN 0 WHEN ps.status = 'closed' THEN ps.dwell_seconds ELSE GREATEST(0, FLOOR(EXTRACT(EPOCH FROM (NOW() - ps.arrival_at))))::bigint END ), 0)::bigint AS dwellSeconds, COUNT(ps.id) FILTER (WHERE ps.status = 'open')::bigint AS openCount FROM camera c LEFT JOIN presence_sessions ps ON ps.camera_id = c.id AND ps.arrival_at >= AND ps.arrival_at < WHERE c.online_status = 'online'
AND c.id = #{cameraId}
GROUP BY c.id, c.device_name, c.serial_no, c.channel_no ORDER BY sessionCount DESC, c.id

SELECT bl.id AS logId, bl.person_id AS personId, COALESCE(p.display_name, '未知访客') AS displayName, COALESCE(p.person_type::text, 'stranger') AS personKind, bl.event_type AS eventType, bl.event_time AS eventTime, c.device_name AS deviceName, COALESCE(NULLIF(p.face_image_url, ''), fp.image_url, NULLIF(bl.face_image_url, '')) AS faceImageUrl FROM behavior_logs bl INNER JOIN camera c ON c.id = bl.camera_id LEFT JOIN persons p ON p.id = bl.person_id LEFT JOIN LATERAL ( SELECT image_url FROM face_profiles WHERE person_id = bl.person_id ORDER BY quality_score DESC NULLS LAST, id LIMIT 1 ) fp ON bl.person_id IS NOT NULL WHERE bl.event_time >= #{beginDate}::timestamp AND bl.event_time < (#{endDate}::date + INTERVAL '1 day') AND bl.event_type IN ('enter', 'exit') AND p.person_type IN ('student', 'staff')
AND bl.camera_id = #{cameraId}
ORDER BY bl.event_time DESC LIMIT #{limit}

SELECT x.track_key AS trackKey, COALESCE(x.display_name, '未知访客') AS displayName, COALESCE(fp.image_url, x.session_face_url, '') AS faceImageUrl, x.person_id AS mergedPersonId, COALESCE(c.install_location, c.device_name, '—') AS locationName, x.arrival_at AS arrivalAt, COALESCE(x.person_type, 'stranger') AS personType, COALESCE(x.employee_no, '') AS employeeNo, COALESCE(x.gender, '2') AS gender, COALESCE(x.phone, '') AS phone, COALESCE(x.note, '') AS note, COALESCE(enter_log.snapshot_url, '') AS snapshotUrl, enter_log.snapshot_bbox AS snapshotBbox, COALESCE(clip.video_url, '') AS clipVideoUrl FROM ( SELECT DISTINCT ON (ps.track_key) ps.id AS session_id, ps.track_key, ps.camera_id, ps.person_id, p.display_name, p.person_type::text AS person_type, p.employee_no, p.gender, p.phone, p.note, ps.arrival_at, ps.face_image_url AS session_face_url FROM presence_sessions ps LEFT JOIN persons p ON p.id = ps.person_id WHERE ps.track_key IS NOT NULL AND ps.track_key <> '' AND ps.arrival_at >= #{beginDate}::date AND ps.arrival_at < (#{endDate}::date + INTERVAL '1 day')
AND ps.camera_id = #{cameraId}
AND (ps.person_id IS NULL OR p.person_type = 'stranger') ORDER BY ps.track_key, ps.arrival_at DESC ) x LEFT JOIN camera c ON c.id = x.camera_id LEFT JOIN LATERAL ( SELECT image_url FROM face_profiles WHERE person_id = x.person_id ORDER BY quality_score DESC NULLS LAST, id LIMIT 1 ) fp ON x.person_id IS NOT NULL LEFT JOIN LATERAL ( SELECT bl.snapshot_url, bl.snapshot_bbox FROM behavior_logs bl WHERE bl.event_type = 'enter' AND bl.camera_id = x.camera_id AND (bl.session_id = x.session_id OR bl.track_key = x.track_key) AND bl.snapshot_url IS NOT NULL AND TRIM(bl.snapshot_url) <> '' ORDER BY CASE WHEN bl.session_id = x.session_id THEN 0 ELSE 1 END, ABS(EXTRACT(EPOCH FROM (bl.event_time - x.arrival_at::timestamp))) LIMIT 1 ) enter_log ON TRUE LEFT JOIN LATERAL ( SELECT pvc.video_url FROM presence_video_clips pvc WHERE pvc.camera_id = x.camera_id AND pvc.start_time <= x.arrival_at + INTERVAL '5 seconds' AND pvc.end_time >= x.arrival_at - INTERVAL '5 seconds' ORDER BY ABS(EXTRACT(EPOCH FROM (pvc.start_time - x.arrival_at))) LIMIT 1 ) clip ON TRUE ORDER BY x.arrival_at DESC

mapper.update:
UPDATE presence_sessions
SET person_id = NULL, updated_at = NOW()
WHERE track_key = #{trackKey}

UPDATE presence_sessions
SET person_id = #{personId}, updated_at = NOW()
WHERE track_key = #{trackKey}

mapper.select:
SELECT * FROM ( SELECT p.id AS personId, p.display_name AS displayName, COALESCE(p.employee_no, '') AS employeeNo, p.person_type::text AS personKind, CASE WHEN pda.attendance_status::text = 'absent' THEN COALESCE(pda.camera_id, ll.camera_id) ELSE ll.camera_id END AS cameraId, CASE WHEN pda.attendance_status::text = 'absent' THEN COALESCE(c_manual.device_name, ll.device_name) ELSE ll.device_name END AS locationName, CASE WHEN pda.attendance_status::text = 'absent' THEN 'absent' WHEN COALESCE(sir.overlapped, FALSE) = FALSE THEN 'absent' WHEN COALESCE(sir.present_at_end, FALSE) = TRUE THEN 'present' ELSE 'left' END AS attendanceStatus, CASE WHEN pda.attendance_status::text = 'absent' THEN 0 ELSE COALESCE(pc.enter_count, 0) END AS enterCount, CASE WHEN pda.attendance_status::text = 'absent' THEN 0 ELSE COALESCE(pc.exit_count, 0) END AS exitCount, CASE WHEN pda.attendance_status::text = 'absent' THEN NULL ELSE sir.first_arrival END AS arrivalAt, CASE WHEN pda.attendance_status::text = 'absent' THEN NULL WHEN COALESCE(sir.present_at_end, FALSE) THEN NULL WHEN sir.last_departure IS NULL THEN NULL WHEN sir.first_arrival IS NOT NULL AND sir.last_departure < sir.first_arrival THEN NULL ELSE sir.last_departure END AS departureAt, CASE WHEN pda.attendance_status::text = 'absent' THEN 0 ELSE COALESCE(sir.dwell_seconds, 0) END AS dwellSeconds, CASE WHEN pda.attendance_status::text = 'absent' THEN FALSE ELSE COALESCE(sir.overlapped, FALSE) END AS overlapped FROM persons p LEFT JOIN person_daily_attendance pda ON pda.person_id = p.id AND pda.stat_date = #{beginDate}::date LEFT JOIN camera c_manual ON c_manual.id = pda.camera_id LEFT JOIN ( SELECT ps.person_id, BOOL_OR( ps.arrival_at < AND (ps.status = 'open' OR COALESCE(ps.departure_at, NOW()) > ) ) AS overlapped, BOOL_OR( ps.arrival_at <= AND ps.status = 'open' ) AS present_at_end, MIN(ps.arrival_at) FILTER ( WHERE ps.arrival_at < AND (ps.status = 'open' OR COALESCE(ps.departure_at, NOW()) > ) ) AS first_arrival, MAX(ps.departure_at) FILTER ( WHERE ps.status = 'closed' AND ps.departure_at IS NOT NULL AND ps.departure_at >= ps.arrival_at AND ps.arrival_at < AND ps.departure_at > ) AS last_departure, COALESCE(SUM( CASE WHEN ps.arrival_at < AND (ps.status = 'open' OR COALESCE(ps.departure_at, NOW()) > ) THEN GREATEST(0, FLOOR(EXTRACT(EPOCH FROM ( LEAST( CASE WHEN ps.status = 'closed' AND ps.departure_at IS NOT NULL AND ps.departure_at >= ps.arrival_at THEN ps.departure_at ELSE NOW() END, , NOW() ) - GREATEST(ps.arrival_at, ) ))))::bigint ELSE 0 END ), 0)::bigint AS dwell_seconds FROM presence_sessions ps WHERE ps.person_id IS NOT NULL
AND ps.camera_id = #{cameraId}
GROUP BY ps.person_id ) sir ON sir.person_id = p.id LEFT JOIN ( SELECT DISTINCT ON (ps.person_id) ps.person_id, ps.camera_id, c.device_name FROM presence_sessions ps INNER JOIN camera c ON c.id = ps.camera_id WHERE ps.person_id IS NOT NULL AND ps.arrival_at < AND (ps.status = 'open' OR COALESCE(ps.departure_at, NOW()) > )
AND ps.camera_id = #{cameraId}
ORDER BY ps.person_id, ps.arrival_at DESC ) ll ON ll.person_id = p.id LEFT JOIN ( SELECT bl.person_id, COUNT(*) FILTER (WHERE bl.event_type = 'enter')::bigint AS enter_count, COUNT(*) FILTER (WHERE bl.event_type = 'exit')::bigint AS exit_count FROM behavior_logs bl WHERE bl.person_id IS NOT NULL AND bl.event_type IN ('enter', 'exit') AND bl.event_time >= AND bl.event_time <
AND bl.camera_id = #{cameraId}
GROUP BY bl.person_id ) pc ON pc.person_id = p.id
AND p.person_type IN ('student', 'staff')
AND p.person_type::text = #{filter.personType}
AND ( EXISTS (SELECT 1 FROM face_profiles fp WHERE fp.person_id = p.id) OR COALESCE(p.face_image_url, '') <> '' OR EXISTS ( SELECT 1 FROM presence_sessions ps2 WHERE ps2.person_id = p.id AND ps2.arrival_at < AND (ps2.status = 'open' OR COALESCE(ps2.departure_at, NOW()) > )
AND ps2.camera_id = #{cameraId}
) OR pda.person_id IS NOT NULL )
AND p.display_name ILIKE CONCAT('%', #{filter.displayName}, '%')
AND COALESCE(p.employee_no, '') ILIKE CONCAT('%', #{filter.employeeNo}, '%')
) attendance_rows
AND attendanceStatus = 'absent'
AND attendanceStatus = 'present'
AND attendanceStatus = 'left'
AND attendanceStatus = 'present'
AND attendanceStatus = 'left'
ORDER BY dwellSeconds DESC, displayName ASC LIMIT #{limit}
